//! The compact word lists fake values are built from (`testdata/Words.kt`), generated from it. Kept small on
//! purpose: variety comes from combining them.

/// First and last names that belong together; `family_first` cultures write the family name first in a full name,
/// and `middle` names go between (Vietnamese full names usually have one).
pub struct NamePool {
    pub first: &'static [&'static str],
    pub last: &'static [&'static str],
    pub family_first: bool,
    pub weight: i32,
    pub middle: &'static [&'static str],
}

